package com.tekwatt.tariff.service;import com.tekwatt.tariff.dto.*;import com.tekwatt.tariff.entity.*;import com.tekwatt.tariff.repository.TariffRepository;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;
@Service @Transactional public class TariffService {private final TariffRepository repo;public TariffService(TariffRepository r){repo=r;}public TariffResponse create(TariffRequest r){validate(r);if(repo.existsByTenantIdAndCodeIgnoreCase(r.tenantId(),r.code()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Tariff code already exists");return TariffResponse.from(repo.save(new Tariff(r.tenantId(),r.code().toUpperCase(),r.name(),r.energyPricePerKwh(),r.timePricePerMinute(),r.sessionFee(),r.taxPercent(),r.currency(),r.validFrom(),r.validTo())));}@Transactional(readOnly=true)public TariffResponse get(UUID id){return TariffResponse.from(find(id));}@Transactional(readOnly=true)public List<TariffResponse> list(UUID tenantId){return repo.findAllByTenantIdOrderByCreatedAtDesc(tenantId).stream().map(TariffResponse::from).toList();}public TariffResponse update(UUID id,TariffRequest r){validate(r);Tariff t=find(id);if(!t.getTenantId().equals(r.tenantId())||!t.getCode().equalsIgnoreCase(r.code()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"tenantId and code cannot be changed");t.update(r.name(),r.energyPricePerKwh(),r.timePricePerMinute(),r.sessionFee(),r.taxPercent(),r.currency(),r.validFrom(),r.validTo());return TariffResponse.from(t);}public TariffResponse status(UUID id,TariffStatusRequest r){Tariff t=find(id);t.setStatus(r.status());return TariffResponse.from(t);}private void validate(TariffRequest r){if(r.validTo()!=null&&!r.validTo().isAfter(r.validFrom()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"validTo must be after validFrom");}private Tariff find(UUID id){return repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Tariff not found"));}}
